    // initial point: `state` with zero error by definition
    out << Step{.next=state, .error_squared=0};

    auto& [t, dt, curr]  = state;
    auto& [x, xp] = curr;
    for (;;) {
        Vec advanced{
            .x = x + xp * dt,
            .xp = xp + acceleration(x) * dt
        };
        const Step step = one_step(state, advanced);
        state = step.next;
        out << step;
    }
