    // Coefficients e_i = b5_i - b4_i from the Butcher tableau.
    const Vec err_vec = dt * ((71.0L/57600)*k1 + (-71.0L/16695)*k3 + (71.0L/1920)*k4 + (-17253.0L/339200)*k5 + (22.0L/525)*k6 + (-1.0L/40)*k7);

