}

void simulate(std::ostream& out, State state) {
    out << Step{.next=state, .error_squared=0};
    for (;;) {
        const Step step = dopri5_step(state);
        state = step.next;
        out << step;
    }
}

int main() {
    const State start{
        .t = 0,
        .dt = 0.001,
        .current = Vec{.x = 6371000, .xp = 0 }
    };
